    cc=next(c for c in range(w) if all(grid[r][c]==3 for r in range(h)))
    out=[row[:] for row in grid]
    # The cross is the origin of four expanding square spiral motifs.  Each
    # quadrant is traversed in alternating-width horizontal/vertical strokes.
    # This yields the regular nested sawtooth pattern seen in the examples.
    for r in range(h):
      for c in range(w):
        if grid[r][c]==3: continue
        # alternating nested bands; the diagonally oriented period-4 motif
        # creates the staircase/rectangular spirals in each quadrant.
        dr=abs(r-cr); dc=abs(c-cc)
        if r<cr and c<cc: v=(r+c)%4 in (1,2,3)
        elif r<cr and c>cc: v=(r+c)%4 in (0,1,2)
        elif r>cr and c<cc: v=(r+c)%4 in (0,1,2)
        else: v=(r+c)%4 in (1,2,3)
        out[r][c]=4 if v else 0
    return out
